// header.h
inline int compute(int x) {
    return x * x + 1;
}

// file1.cpp
#include "header.h"
int result1 = compute(5);  // Emits weak symbol

// file2.cpp  
#include "header.h"
int result2 = compute(10); // Emits weak symbol

// Linking: Both translation units have compute().
// Without inline → multiple definition error
// With inline → linker keeps one, discards the other

// Check with:
// $ nm file1.o | grep compute
// 0000000000000000 W _Z7computei   # W = weak
// $ nm file2.o | grep compute  
// 0000000000000000 W _Z7computei   # W = weak
